function editorHasFocus(){const el=document.activeElement;return !!el&&!!el.matches&&el.matches('input,textarea,select,[contenteditable="true"]')}
function queueRowsHtml(){return state.queue.slice(-30).map(q=>`<div class="queue-row"><span class="qstatus ${q.status}">${q.status}</span><strong>#${q.sequence_no} ${q.command_type}</strong><small>${q.command_type==='TEACH'?`${(q.payload.labels||[]).join(' ')} · ${q.payload.context_id||''}`:q.command_type==='EXPERIENCE'?`${q.payload.event_key||''} · ${(q.payload.concept_labels||[]).join(' ')}`:(q.payload.cue_labels||[]).join(' ')}</small></div>`).join('')||'<div class="empty">Queue is empty. Add teaching items, then RUN or STEP ITEM.</div>'}
function eventRowsHtml(){return [...state.events].reverse().map(ev=>`<div class="event-row"><span class="prov ${provenance(ev.event_type).toLowerCase()}">${provenance(ev.event_type)}</span><div><strong>${ev.event_type}</strong><small>cycle ${ev.engine_cycle} · rev ${ev.state_revision} · ${short(ev.event_id,18)}</small></div></div>`).join('')||'<div class="empty">Waiting for recorded events…</div>'}
function patchLiveDOM(){
  const foot=document.querySelector('[data-live="aside-foot"]');
  if(foot)foot.innerHTML=`<div class="dot ${state.socketState}"></div>${state.selectedRun?short(state.selectedRun,18):'No run selected'}`;
  const header=document.querySelector('[data-live="header-actions"]');
  if(header)header.innerHTML=`${state.status?.dirty?'<div class="pill warning">● UNSAVED DEVELOPMENT</div>':''}<div class="pill ${state.status?.worker_alive?'ok':''}">${state.status?.worker_alive?'ENGINE ONLINE':'ENGINE OFFLINE'}</div>`;
  if(state.page==='Cultivate'){
    const metricBox=document.querySelector('[data-live="metrics"]');if(metricBox)metricBox.innerHTML=metrics();
    const readout=document.querySelector('[data-live="execution"]');if(readout)readout.innerHTML=`<span>EXECUTION</span><strong>${esc(state.status?.execution?.state||'—')}</strong><small>${state.status?.execution?.queue_counts?.queued||0} queued · cursor ${state.cursor}</small>`;
    const queue=document.querySelector('[data-live="queue"]');if(queue)queue.innerHTML=queueRowsHtml();
    const events=document.querySelector('[data-live="events"]');if(events)events.innerHTML=eventRowsHtml();
    const eventMeta=document.querySelector('[data-live="event-meta"]');if(eventMeta)eventMeta.textContent=`${state.events.length} buffered · ${state.status?.descriptor?`cycle ${state.status.descriptor.cycle}`:'offline'}`;
    const running=state.status?.execution?.state==='running';
    const setDisabled=(action,value)=>{const el=document.querySelector(`[data-action="${action}"]`);if(el)el.disabled=!!value};
    setDisabled('start',running);setDisabled('step',running);setDisabled('teach-now',running);setDisabled('probe-now',running);
  }
  if(state.page==='Explorer')requestAnimationFrame(()=>drawLivingCanvas());
}
function backgroundRender(force=false){
  // force is retained for call-site compatibility, but background traffic only
  // patches dedicated live regions; it never destroys user-editable controls.
  patchLiveDOM();
}
