function provenance(t){if(t==='EVIDENCE_ACCEPTED')return'OBSERVED';if(t==='PLASTICITY_CHANGED')return'ASSOCIATED';if(t.includes('CANDIDATE'))return'MANUFACTURED';if(t.includes('PROMOTED'))return'PROMOTED';if(t.includes('USED')||t.includes('INTERACTION'))return'USED';if(t.includes('CHALLENGE'))return'CHALLENGED';if(t.includes('REFOLD'))return'REFOLDED';if(t.startsWith('RUN_')||t==='CHECKPOINT_SAVED'||t==='CURRICULUM_QUEUED')return'PROGRAMMED';return'ENGINE'}
async function refreshCurricula(){if(!state.projectId){state.curricula=[];return}try{state.curricula=await api.curricula(state.projectId)}catch(e){state.error=e.message}}
async function refreshExperiments(doRender=false){if(!state.projectId){state.experiments=[];return}try{state.experiments=await api.experiments(state.projectId);if(state.selectedExperiment&&!state.experiments.some(x=>x.experiment_id===state.selectedExperiment))state.selectedExperiment='';if(!state.selectedExperiment&&state.experiments[0])state.selectedExperiment=state.experiments[0].experiment_id;if(state.selectedExperiment){state.experimentDetail=await api.experiment(state.selectedExperiment);const runs=state.experimentDetail.runs||[];if(state.selectedExperimentRun&&!runs.some(x=>x.experiment_run_id===state.selectedExperimentRun))state.selectedExperimentRun='';if(!state.selectedExperimentRun&&runs.length)state.selectedExperimentRun=runs[runs.length-1].experiment_run_id;if(state.selectedExperimentRun)state.experimentRunDetail=await api.experimentRunStatus(state.selectedExperimentRun)}}catch(e){state.error=e.message}if(doRender)backgroundRender(true)}
